INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (4421, 1, '<spring-waterfront-retro@company.example>', 'Spring waterfront outing closeout', 'peopleops@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-05-07T16:42:00+08:00', 'The April waterfront walk closed with 31 attendees and no on-water activity. Two guests used the indoor accessibility route, and the unused ferry block was released before the cancellation deadline. Keep the accessibility note for future venue comparisons.', NULL, 1, 0, 0, NULL, NULL, '{}', 6142, 267, '2026-05-07T16:42:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (5174, 1, '<invoice-correction-harbor-lunch@company.example>', 'Resolved invoice mismatch from harbor lunch', 'finance-control@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-05-19T10:18:00+08:00', 'The Harbor Lane lunch invoice was corrected from CNY 8,460 to CNY 8,040 after four boxed meals were removed. The approved counterparty remained Harbor Lane Catering Ltd.; the temporary personal QR code in the first quote was rejected.', NULL, 1, 1, 0, NULL, NULL, '{}', 7254, 248, '2026-05-19T10:18:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (6388, 1, '<waiver-clinic-june@company.example>', 'June waiver clinic lessons', 'risk-control@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-06-03T14:27:00+08:00', 'For the June paddle clinic, signed water waivers were matched to the final manifest one business day before departure. Verbal consent and manager confirmation were not accepted as substitutes, and three incomplete participants were reassigned to shore support.', NULL, 1, 0, 0, NULL, NULL, '{}', 8365, 273, '2026-06-03T14:27:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (7046, 1, '<family-shore-program@company.example>', 'Family shore program vendor notes', 'family-programs@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-06-11T11:06:00+08:00', 'A prior family day used a shaded pier walk, knot-tying table, and early dinner for minors and guests who did not join the licensed boat activity. The dry-land vendor supplied two child-size lifejackets only for demonstrations, not boarding.', NULL, 1, 0, 0, NULL, NULL, '{}', 9472, 259, '2026-06-11T11:06:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (7793, 1, '<shuttle-rehearsal-west-gate@company.example>', 'West gate shuttle rehearsal notes', 'facilities@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-06-18T17:35:00+08:00', 'The 37-seat coach needed eleven minutes to load at the west gate because equipment cases blocked the curb. Facilities recommends a 20-minute assembly buffer, a separate carton van, and a named dispatcher at both ends.', NULL, 0, 0, 0, NULL, NULL, '{}', 1586, 230, '2026-06-18T17:35:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (8452, 1, '<allergen-matrix-tide-annex@company.example>', 'Tide Annex allergen matrix review', 'wellbeing@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-06-24T09:48:00+08:00', 'The Tide Annex kitchen confirmed a shellfish-free plated option but could not guarantee a separate fryer. For a previous 26-person dinner, the team used sealed vegetarian meals for two participants and recorded meal labels only with the catering lead.', NULL, 0, 1, 0, NULL, NULL, '{}', 2649, 255, '2026-06-24T09:48:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (9186, 1, '<gallery-retention-review@company.example>', 'Internal gallery retention review', 'hr-forms@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-01T13:22:00+08:00', 'The May gallery was limited to the employee portal for 45 days. Identifiable images of two withdrawn participants were removed within one business day, while wide venue photographs without identifiable faces remained in the event archive.', NULL, 1, 0, 0, NULL, NULL, '{}', 3798, 251, '2026-07-01T13:22:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (4635, 1, '<marina-lost-property@company.example>', 'Closed: marina lost-property case', 'guest-services@haiwan-marina.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-06T15:51:00+08:00', 'A navy windbreaker from the June client visit was collected at Pier A reception. The case is closed; collection required the original claim number and did not involve the Pier B group-activity desk.', NULL, 1, 0, 0, NULL, NULL, '{}', 4813, 199, '2026-07-06T15:51:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (5298, 1, '<insurance-comparison-rowing-day@company.example>', 'Rowing day insurance comparison', 'insurance-desk@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-09T10:33:00+08:00', 'For the July rowing proposal, Harbor Basic excluded self-operated craft and covered only 20 named adults. CrewSafe Group allowed named adult day units but still required a final roster and certificate issuance before activity confirmation.', NULL, 0, 1, 0, NULL, NULL, '{}', 5937, 237, '2026-07-09T10:33:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (6712, 1, '<emergency-tree-drill@company.example>', 'Emergency contact tree drill result', 'security-operations@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-14T16:04:00+08:00', 'The contact-tree drill reached all four coordinators in six minutes. The outdated extension for the north reception desk was replaced with 021-5555-0836, and the next drill should include the transport dispatcher.', NULL, 1, 0, 0, NULL, NULL, '{}', 6724, 222, '2026-07-14T16:04:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (7564, 1, '<ferry-timetable-conflict@company.example>', 'Ferry timetable conflict for museum visit', 'travel-desk@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-17T11:47:00+08:00', 'The 08:40 public ferry cannot support the museum group because the coach arrives at 08:52. The museum visit is unrelated to the September sailing plan; travel desk moved that group to the 09:25 departure.', NULL, 1, 0, 0, NULL, NULL, '{}', 7316, 215, '2026-07-17T11:47:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (8249, 1, '<thunder-cancelled-july-sail@company.example>', 'July client sail cancelled for thunder risk', 'risk-control@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-21T08:26:00+08:00', 'The July 22 client sail was cancelled after the official feed showed lightning risk despite moderate wind. The charter hold was released without charge, and the dinner reservation remained active for the indoor alternative.', NULL, 0, 1, 1, NULL, NULL, '{}', 8429, 233, '2026-07-21T08:26:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (8871, 1, '<dry-land-access-needs@company.example>', 'Dry-land activity access needs', 'workplace-inclusion@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-24T14:39:00+08:00', 'For future coastal events, keep at least one step-free indoor activity, seating near accessible restrooms, and an option that does not require disclosing a diagnosis. Individual accommodations should stay in the restricted coordinator channel.', NULL, 0, 0, 0, NULL, NULL, '{}', 9068, 259, '2026-07-24T14:39:00+08:00');
INSERT INTO messages (id, folder_id, message_id, subject, from_addr, to_addr_json, cc_addr_json, bcc_addr_json, date, body_text, body_html, is_read, is_important, is_flagged, in_reply_to, references_header, headers_json, uid, size, created_at) VALUES (9536, 1, '<offsite-ledger-close@company.example>', 'Northshore offsite ledger closed', 'finance-control@company.example', '["lin.qiao@company.example"]', '[]', '[]', '2026-07-28T17:13:00+08:00', 'The Northshore offsite ledger closed at CNY 46,780 against a CNY 50,000 cap. Three official invoices matched the approval memo; a duplicate CNY 1,200 transport request was voided before posting.', NULL, 0, 1, 0, NULL, NULL, '{}', 9781, 215, '2026-07-28T17:13:00+08:00');
